function flightSimulator(canvasId) {
  // =========================
  // INTENTIONAL BUGS MARKER
  // This simulator deliberately includes bugs:
  // 1. Instrument lag during high G-force.
  // 2. Altimeter stickiness at certain altitudes.
  // 3. Compass deviation near magnetic anomalies.
  // 4. Engine power fluctuation during steep climbs.
  // Visual indicators are drawn when bugs affect instruments.
  // =========================
  const canvas = document.getElementById(canvasId);
  if (!canvas) throw new Error("Canvas not found");
  canvas.width = 500;
  canvas.height = 500;
  const ctx = canvas.getContext("2d");

  // Simulation state
  let throttle = 0.5; // 0 to 1
  let pitch = 0; // radians
  let roll = 0; // radians
  let yaw = 0; // radians (heading)
  let speed = 0; // knots
  let altitude = 0; // feet
  let fuel = 1000; // liters
  const maxFuel = 1000;
  const minThrottle = 0.2;
  const maxSpeed = 300; // knots
  const maxPitch = Math.PI / 6; // +/-30°
  const maxRoll = Math.PI / 4; // +/-45°
  const maxYawChange = Math.PI / 180 * 2; // 2° per frame

  // Display values (instrument readings)
  let displaySpeed = 0;
  let displayAltitude = 0;
  let displayHeading = 0;
  let displayFuel = fuel;

  // Bug state
  let gLoad = 1; // 1g baseline
  const G_THRESHOLD = 1.5; // when G > 1.5, lag increases
  const ALT_STICK_LOW = 4900; // ft
  const ALT_STICK_HIGH = 5200; // ft
  let altStuckValue = null;
  let altStuckTimer = 0;
  const ALT_STICK_DURATION = 2; // seconds
  let compassAnomalyZone = { heading: 180, radius: 30 }; // degrees
  let compassError = 0;
  let powerFluctuation = 1;

  // Input state
  const keys = {};
  window.addEventListener("keydown", e => keys[e.code] = true);
  window.addEventListener("keyup", e => keys[e.code] = false);

  // Simple terrain generator using sine waves
  function terrainHeight(x) {
    const freq = 0.005;
    const amp = 200;
    return Math.sin(freq * (x + altitude / 10)) * amp;
  }

  // Update simulation
  function update(dt) {
    // Throttle control (ensuring cannot go below minThrottle if above stall)
    if (keys["ArrowUp"]) throttle = Math.min(1, throttle + 0.5 * dt);
    if (keys["ArrowDown"]) throttle = Math.max(minThrottle, throttle - 0.5 * dt);

    // Pitch control
    if (keys["KeyW"]) pitch = Math.min(maxPitch, pitch + 0.5 * dt);
    if (keys["KeyS"]) pitch = Math.max(-maxPitch, pitch - 0.5 * dt);

    // Roll control
    if (keys["KeyA"]) roll = Math.max(-maxRoll, roll - 0.5 * dt);
    if (keys["KeyD"]) roll = Math.min(maxRoll, roll + 0.5 * dt);

    // Yaw control
    if (keys["ArrowLeft"]) yaw = (yaw - maxYawChange) % (2 * Math.PI);
    if (keys["ArrowRight"]) yaw = (yaw + maxYawChange) % (2 * Math.PI);

    // Simplified physics
    // Engine performance reduces at steep climb
    const climbRate = Math.cos(pitch) * speed * Math.tan(pitch);
    powerFluctuation = 1 - Math.min(0.25, Math.max(0, (Math.abs(pitch) - 0.3) / 0.3) * 0.4);

    const throttleEff = throttle * powerFluctuation;
    const thrust = throttleEff * maxSpeed;
    const drag = 0.01 * speed;
    speed = speed + (thrust - drag) * dt;
    speed = Math.max(0, speed);

    // Update altitude based on pitch
    const climb = Math.tan(pitch) * speed * dt; // feet
    altitude += climb;
    altitude = Math.max(0, altitude - 0.1); // simulate sink in cruise
    fuel -= Math.abs(climb) * 0.01 + throttle * 0.05 * dt; // fuel consumption
    fuel = Math.max(0, fuel);

    // G-load estimation (simplified)
    gLoad = 1 + Math.abs(climb) / 100; // arbitrary mapping
    // Instrument lag during high G
    const speedLagFactor = 1 - Math.min(0.5, Math.max(0, (gLoad - G_THRESHOLD) * 0.8));
    displaySpeed += (speed - displaySpeed) * speedLagFactor;

    // Altimeter stickiness at specific altitudes
    if (altitude >= ALT_STICK_LOW && altitude <= ALT_STICK_HIGH) {
      if (altStuckValue === null) {
        altStuckValue = displayAltitude;
        altStuckTimer = 0;
      } else {
        altStuckTimer += dt;
        if (altStuckTimer > ALT_STICK_DURATION) {
          displayAltitude += (altitude - displayAltitude) * 0.05;
        }
      }
    } else {
      altStuckValue = null;
      altStuckTimer = 0;
      displayAltitude += (altitude - displayAltitude) * 0.05;
    }

    // Compass deviation near anomaly
    const headingDeg = (yaw * 180 / Math.PI) % 360;
    const diffToAnomaly = ((headingDeg - compassAnomalyZone.heading + 540) % 360) - 180;
    if (Math.abs(diffToAnomaly) < compassAnomalyZone.radius) {
      compassError = Math.sin((diffToAnomaly / compassAnomalyZone.radius) * Math.PI) * 10;
    } else {
      compassError = 0;
    }
    displayHeading = headingDeg + compassError;
    displayHeading = (displayHeading + 360) % 360;

    // Fuel display
    displayFuel = fuel;
  }

  // Render scene
  function render() {
    ctx.fillStyle = "#003366"; // sky color
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Horizon calculation
    const horizonY = canvas.height / 2 - pitch * 100;

    // Draw terrain
    const skyGradient = ctx.createLinearGradient(0, 0, 0, horizonY);
    skyGradient.addColorStop(0, "#000080");
    skyGradient.addColorStop(1, "#003366");
    ctx.fillStyle = skyGradient;
    ctx.fillRect(0, 0, canvas.width, horizonY);

    const groundGradient = ctx.createLinearGradient(0, horizonY, 0, canvas.height);
    groundGradient.addColorStop(0, "#006600");
    groundGradient.addColorStop(1, "#004400");
    ctx.fillStyle = groundGradient;
    const terrainPath = new Path2D();
    terrainPath.moveTo(0, horizonY);
    for (let x = 0; x <= canvas.width; x += 2) {
      const y = horizonY + terrainHeight(x) * 2; // scale
      terrainPath.lineTo(x, y);
    }
    terrainPath.lineTo(canvas.width, canvas.height);
    terrainPath.lineTo(0, canvas.height);
    terrainPath.closePath();
    ctx.fill(terrainPath);

    // Draw horizon line
    ctx.strokeStyle = "white";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, horizonY);
    ctx.lineTo(canvas.width, horizonY);
    ctx.stroke();

    // Draw HUD
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    ctx.fillRect(0, canvas.height - 120, canvas.width, 120);

    // HUD text
    ctx.font = "14px monospace";
    ctx.fillStyle = "white";
    ctx.textBaseline = "top";
    const hudLines = [
      { label: "SPD", value: displaySpeed.toFixed(1), unit: "kt" },
      { label: "ALT", value: displayAltitude.toFixed(0), unit: "ft" },
      { label: "HDG", value: displayHeading.toFixed(0), unit: "°" },
      { label: "FUEL", value: displayFuel.toFixed(0), unit: "L" }
    ];
    hudLines.forEach((item, i) => {
      const text = `${item.label}: ${item.value} ${item.unit}`;
      ctx.fillText(text, 10, canvas.height - 110 + i * 20);
    });

    // Bug visual indicators
    // 1. Speed lag indicator
    if (gLoad > G_THRESHOLD) {
      ctx.fillStyle = "red";
      ctx.beginPath();
      ctx.arc(140, canvas.height - 80, 8, 0, 2 * Math.PI);
      ctx.fill();
      ctx.fillStyle = "white";
      ctx.fillText("LAG", 152, canvas.height - 90);
    }

    // 2. Altimeter stickiness indicator
    if (altStuckValue !== null) {
      ctx.fillStyle = "red";
      ctx.beginPath();
      ctx.arc(140, canvas.height - 60, 8, 0, 2 * Math.PI);
      ctx.fill();
      ctx.fillStyle = "white";
      ctx.fillText("STICK", 152, canvas.height - 70);
    }

    // 3. Compass deviation indicator
    if (Math.abs(compassError) > 0.1) {
      ctx.fillStyle = "red";
      ctx.beginPath();
      ctx.arc(140, canvas.height - 40, 8, 0, 2 * Math.PI);
      ctx.fill();
      ctx.fillStyle = "white";
      ctx.fillText("DEVIATE", 152, canvas.height - 50);
    }

    // 4. Engine power fluctuation indicator
    if (pitch > 0.4 || pitch < -0.4) {
      ctx.fillStyle = "red";
      ctx.beginPath();
      ctx.arc(140, canvas.height - 20, 8, 0, 2 * Math.PI);
      ctx.fill();
      ctx.fillStyle = "white";
      ctx.fillText("POWER", 152, canvas.height - 30);
    }
  }

  // Main loop
  let lastTime = null;
  function loop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;
    update(dt);
    render();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
}
